import{_ as o,l as n,o as r,c as l,v as e,p as s,x as t,d as p,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"保留价","description":"","frontmatter":{"title":"保留价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/auction-reserve.md","filePath":"econ/auction-reserve.md","lastUpdated":1789023840000}'),d={name:"econ/auction-reserve.md"};function _(m,a,u,v,E,A){const i=n("Mermaid");return r(),l("div",null,[a[1]||(a[1]=e('<h1 id="保留价" tabindex="-1">保留价 <a class="header-anchor" href="#保留价" aria-label="Permalink to &quot;保留价&quot;">​</a></h1><div class="epigraph"><p>最优保留价由虚拟价值过零处决定，不随投标人数上升而下降；卖家故意留下正概率不成交，用效率换信息租金。</p><footer>—— Myerson, Optimal Auction Design, Mathematics of Operations Research, 1981；Riley and Samuelson, Optimal Auctions, American Economic Review, 1981</footer></div><p><a href="/econ/second-price-vickrey">上一课</a>钉了二价占优真话：最高报价得物，付第二高。缺口是卖方自己的估值 \\(v_0\\)（常取 \\(0\\)）不必等于「必须成交」。加上保留价 \\(r\\)：所有报价低于 \\(r\\) 则物品留在卖方。真话仍占优，但配置不再总把物品交给最高 \\(v_i\\)。本课钉最优 \\(r\\)，不把收入等价的整条包络提前，也不把虚拟价值熨平写成全书。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对称 IPV，风险中性。二价加保留价：报 \\(v_i\\) 仍是占优；若最高报价 \\(\\lt r\\)，不成交；若恰好一人超过 \\(r\\)，付 \\(r\\)；若至少两人超过 \\(r\\)，付第二高报价。卖方期望收入随 \\(r\\) 先升后降：太低则把物品廉价卖给接近 \\(0\\) 的类型；太高则经常卖不掉。</p><p>Myerson / Riley–Samuelson：正则分布下，最优 \\(r^*\\) 满足虚拟价值为零，</p> \\[\\varphi(r^*)=r^*-\\frac{1-F(r^*)}{f(r^*)}=0 \\]<p>（卖方估值 \\(v_0=0\\) 时）。关键比较静态：\\(r^*\\) <strong>不依赖</strong> \\(n\\)。多一个投标人提高成交概率，但不改变「边际类型该不该拿货」的虚拟价值公式。</p><h3 id="不是「多来几个人就可以把-降到零」" tabindex="-1">不是「多来几个人就可以把 \\(r\\) 降到零」 <a class="header-anchor" href="#不是「多来几个人就可以把-降到零」" aria-label="Permalink to &quot;不是「多来几个人就可以把 $r$ 降到零」&quot;">​</a></h3><p>直觉说竞争越狠越不必设门槛。最优拍卖的会计相反：低类型成交会通过激励相容抬高所有更高类型的信息租金。挡掉 \\(\\varphi\\lt 0\\) 的类型，是在砍租金，不是在跟人数作对。人数进的是期望成交量，不进 \\(r^*\\) 的一阶条件。</p><p><span class="marginnote">若卖方自己有 \\(v_0\\gt 0\\)，门槛改成 \\(\\varphi(r)=v_0\\)。物品留在卖方，当且仅当所有投标人的虚拟价值都低于 \\(v_0\\)。有效性要求 \\(r=v_0\\)；收入最大化通常 \\(r^*\\gt v_0\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：对称独立、正则 \\(\\varphi\\) 递增、单物品。在二价（或英式）上加 \\(r\\)，用占优真话把期望收入写成 \\(r\\) 的函数，求导得 \\(\\varphi(r)=0\\)。一价加保留价改的是遮挡的下边界 \\(b(r)=r\\)，最优 \\(r\\) 在正则下与二价相同——这已经是收入等价的特例，本课只记结论，证明放后课。</p>',13)),(r(),s(c,null,{default:t(()=>[h(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E4%BA%8C%E4%BB%B7%E7%9C%9F%E8%AF%9D%22%5D%20--%3E%20R%5B%22%E5%8A%A0%E4%BF%9D%E7%95%99%E4%BB%B7%20r%22%5D%0A%20%20R%20--%3E%20IC%5B%22%E7%9C%9F%E8%AF%9D%E4%BB%8D%E5%8D%A0%E4%BC%98%22%5D%0A%20%20R%20--%3E%20INEFF%5B%22%E6%AD%A3%E6%A6%82%E7%8E%87%E4%B8%8D%E6%88%90%E4%BA%A4%22%5D%0A%20%20PHI%5B%22%CF%86(r)%3D0%22%5D%20--%3E%20RSTAR%5B%22r*%20%E4%B8%8D%E9%9A%8F%20n%20%E5%8F%98%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>不对称先验、不规则密度要熨平，最优机制不再是「简单 \\(r\\) + 最高者得」，本课正则对称。英式加保留价：时钟从 \\(r\\) 起跳，或卖方委托出价顶到 \\(r\\)；策略仍是退到 \\(v\\)，只是 \\(v\\lt r\\) 者不参与。荷式 / 一价把下边界改成 \\(b(r)=r\\)，遮挡公式从 \\(r\\) 积分，不从 \\(0\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>包络把卖方收入钉成期望虚拟剩余。配置规则若把物品交给 \\(\\varphi\\lt 0\\) 的人，该项为负，不如留给卖方（\\(\\varphi\\) 记为 \\(0\\) 或 \\(v_0\\)）。保留价正是这道点态规则的公开写法：低于 \\(r^*\\) 的类型赢率为零。效率损失是故意的——与次优税同一逻辑：信息不对称下，第一最佳（总把物品给估值最高者）不可及，除非放弃收入目标。</p><p>人数增加：最高估值的分布往上移，成交更频繁，期望收入上升，但 \\(\\varphi(r)=0\\) 这条切线不变。所以「热门拍品仍设高底价」与「冷门拍品也设底价」可以来自同一公式，差别在 \\(F\\)，不在 \\(n\\)。</p><h3 id="参与约束在最低类型" tabindex="-1">参与约束在最低类型 <a class="header-anchor" href="#参与约束在最低类型" aria-label="Permalink to &quot;参与约束在最低类型&quot;">​</a></h3><p>未参与的人支付为零。保留价把最低成交类型抬到 \\(r^*\\)，其租金为零。更高类型的租金仍是赢率的积分；砍掉低端赢率，整条租金曲线下移。这与筛选课「故意扭曲低类型数量」是同一包络。</p><p><span class="marginnote">进入费与保留价在 IPV 正则下可以互换（把参与门槛写成货币）。实务上公开 \\(r\\) 与隐藏底价、英式里卖方委托出价，实施不同，最优虚拟门槛可以相同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>关联价值、风险厌恶、预算约束下，\\(r^*\\) 依赖 \\(n\\) 或不再由 \\(\\varphi=0\\) 单独给出。合谋时保留价还要防压价。也不要把保留价写成连续交易里的限价——本课是一次性拍卖的门槛。</p><p>后课默认：IPV 正则下最优保留价由虚拟价值过零决定，与人数无关；二价加 \\(r\\) 仍真话。下一课用包络把一价、荷式、英式的期望收入钉在同一条 \\(Q\\) 上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二价加 \\(r\\)：真话仍占优，配置不再总有效。</li><li>最优 \\(r^*\\) 满足 \\(\\varphi(r^*)=0\\)，不随 \\(n\\) 下降。</li><li>卖方用不成交换更低的信息租金。</li><li>有效门槛是 \\(v_0\\)；收入最大化通常更高。</li><li>出处：Myerson, <em>Math. Oper. Res.</em>, 1981；Riley and Samuelson, <em>AER</em>, 1981。</li></ul>',12))])}const D=o(d,[["render",_]]);export{B as __pageData,D as default};
